module parity_8bit (
    input [7:0] in,
    output out
);

    reg [7:0] pp [0:31]; // Partial Product array with 32 entries

    // Generate partial products using AND gates
    generate
        genvar i, j;
        for (i = 0; i < 8; i = i + 1) begin : gen_i
            for (j = 0; j < 8; j = j + 1) begin : gen_j
                if (i * j < 32) begin
                    and (pp[i*j], in[i], in[j]);
                end
            end
        end
    endgenerate

    // Summation network using carry-save approach
    wire [15:0] sum [0:15];
    wire [15:0] carry;

    generate
        for (int k = 0; k < 16; k = k + 1) begin : gen_sum
            // Collect all partial products contributing to this bit
            wire [7:0] terms;
            for (int m = 0; m < 8; m = m + 1) begin
                if (k - m >= 0 && k - m < 8) begin
                    assign terms[m] = pp[m][k - m];
                end else begin
                    assign terms[m] = 1'b0;
                end
            end

            // Sum terms using cascading OR/GATE structure
            wire [7:0] sum_k;
            for (int n = 0; n < 8; n = n + 1) begin
                if (n == 0) begin
                    assign sum_k[n] = terms[0];
                end else if (n == 1) begin
                    assign sum_k[n] = terms[1] | sum_k[n-1];
                end else if (n == 2) begin
                    assign sum_k[n] = terms[2] | sum_k[n-1];
                end else if (n == 3) begin
                    assign sum_k[n] = terms[3] | sum_k[n-1];
                end else if (n == 4) begin
                    assign sum_k[n] = terms[4] | sum_k[n-1];
                end else if (n == 5) begin
                    assign sum_k[n] = terms[5] | sum_k[n-1];
                end else if (n == 6) begin
                    assign sum_k[n] = terms[6] | sum_k[n-1];
                end else if (n == 7) begin
                    assign sum_k[n] = terms[7] | sum_k[n-1];
                end else begin
                    assign sum_k[n] = 1'b0;
                end
            end

            // Assign final sum and carry
            assign sum[k] = sum_k[7];
            assign carry[k] = sum_k[0];
        end
    endgenerate

    // Handle carry-out
    wire carry_out;
    assign carry_out = carry[15];

    // Final multiplication result
    assign out = sum[15] | carry_out;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire [3:0] en;

    // 2-to-4 decoder logic
    assign en[0] = (sel == 2'b00);
    assign en[1] = (sel == 2'b01);
    assign en[2] = (sel == 2'b10);
    assign en[3] = (sel == 2'b11);

    // Tristate buffers for each input
    assign out = en[0] ? in[0] : 1'bz;
    assign out = en[1] ? in[1] : 1'bz;
    assign out = en[2] ? in[2] : 1'bz;
    assign out = en[3] ? in[3] : 1'bz;

endmodule

module majority (
    input a, b, c,
    output out
