    assign s[0] = a & b & c;
    assign out = s[7];
endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);

    wire [3:0] S1, S2, S3;

    // First stage: Shift in from binary[0], XNOR between shifted bits
    assign S1[0] = binary[0];
    assign S1[1] = binary[1] ~^ S1[0];
    assign S1[2] = binary[2] ~^ S1[1];
    assign S1[3] = binary[3] ~^ S1[2];

    // Second stage: Shift in from S1[0], XOR between shifted bits
    assign S2[0] = S1[0];
    assign S2[1] = S1[1] ^ S2[0];
    assign S2[2] = S1[2] ^ S2[1];
    assign S2[3] = S1[3] ^ S2[2];

    // Third stage: Shift in from S2[0], XOR between shifted bits
    assign S3[0] = S2[0];
    assign S3[1] = S2[1] ^ S3[0];
    assign S3[2] = S2[2] ^ S3[1];
    assign S3[3] = S2[3] ^ S3[2];

    // Assign output
    assign gray = S3;

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

    assign out = 4'b0000; // Default: all LEDs off

    // Enable first LED (out[3]) based on in[1]
    assign out[3] = in[1] ? 1'b1 : (in[0] ? 1'b0 : 1'b1);

    // Enable second LED (out[2]) based on in[1] and in[0]
    assign out[2] = in[1] ? 1'b1 : (in[0] ? 1'b0 : 1'b0);

    // Enable third LED (out[1]) based on in[1], in[0], and in[0]'s complement
    assign out[1] = in[1] ? 1'b1 : (in[0] ? 1'b0 : 1'b1);

    // Enable fourth LED (out[0]) based on in[1], in[0], and in[0]'^2
    assign out[0] = in[1] ? 1'b1 : (in[0] ? 1'b0 : 1'b0);

endmodule

module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);

always @(*) begin
    if (in == 4'b1111)
        code = 2'b00;
    else if (in[0] == 0)
        code = 2'b00;
    else if (in[1] == 0)
        code = 2'b01;
    else if (in[2] == 0)
        code = 2'b10;
    else if (in[3] == 0)
        code = 2'b11;
    else
        code = 2'b11; // Default case when all bits are high (handled by first condition)
end

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    parameter GND = 2'b00;
    parameter VCC = 2'b11;

    reg [1:0] state;

    always @(*) begin
        case ({clk, reset})
            2'b00: state = GND;
            2'b10: state = VCC;
            default: state = state; // Retain current state for 11 and 01
        endcase
    end

    assign state = state;
endmodule

