module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);
    wire [1:0] a = {clk, reset};
    wire [1:0] b = {up_request, down_request};
    wire [3:0] seq = {a, b};

    // Check for left shift operations in a or b
    wire a_is_left_shift = (a == 2'b10) || (a == 2'b01);
    wire b_is_left_shift = (b == 2'b10) || (b == 2'b01);

    // Determine rotation based on sequence and left-shift flags
    reg [1:0] rotated_a, rotated_b;
    reg [3:0] rotated_seq;

    always @(*) begin
        // Default rotations (no left shift)
        rotated_a = a;
        rotated_b = b;
        rotated_seq = seq;

        // Check for left shift in a
        if (a_is_left_shift) begin
            rotated_a = {a[0], a[1]}; // Swap bits for left shift
            rotated_seq = {rotated_a, b};
        end

        // Check for left shift in b
        if (b_is_left_shift) begin
            rotated_b = {b[0], b[1]}; // Swap bits for left shift
            rotated_seq = {a, rotated_b};
        end
    end

    // Check if rotation is 180 degrees (example condition)
    wire is_180_rot = (rotated_seq == 4'b1010); // Example value

    assign state = is_180_rot ? 2'b11 : rotated_a;

endmodule

module vending_machine (
    input clk, reset,
