module power (
    input signed [7:0] in_0,
    input signed [3:0] in_1,
    output signed [15:0] out
);

    // Sign-extend in_0 to 12 bits
    wire signed [11:0] sign_ext_in = { {4{in_0[7]}}, in_0 };
    // Sign-extend in_1 to 12 bits
    wire signed [11:0] sign_ext_mult = { {8{in_1[3]}}, in_1 };
    // Compute product and truncate to 16 bits
    assign out = { sign_ext_in * sign_ext_mult };

endmodule

module log2_int (
    input signed [15:0] in_0,
    output signed [7:0] out
);

    reg signed [7:0] approx;

    always @* begin
        if (in_0 < 0) begin
            approx = 0;
        end else if (in_0 < 16'd2500) begin
            approx = 1;
        end else if (in_0 < 16'd5000) begin
            approx = 2;
        end else if (in_0 < 16'd7500) begin
            approx = 3;
        end else if (in_0 < 16'd10000) begin
            approx = 4;
        end else if (in_0 < 16'd12500) begin
            approx = 5;
        end else begin
            approx = 6;
        end
    end

    assign out = approx;

endmodule

module add_8bit (
    input signed [7:0] a, b,
    output signed [8:0] out
);

    // Compute partial products for each bit of a
    wire signed [8:0] pp [7:0];
    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : gen_partial_products
            assign pp[i] = a[i] ? ({1'b0, b} << i) : {1'b0, b, 8'b0};
        end
    endgenerate

    // Summation of partial products using a carry-save approach
    wire signed [8:0] sum0, sum1, sum2;

    assign sum0 = pp[0] + pp[2] + pp[4] + pp[6];
    assign sum1 = pp[1] + pp[3] + pp[5] + pp[7];
    assign sum2 = pp[0] + pp[1] + pp[2] + pp[3] + pp[4] + pp[5] + pp[6] + pp[7];

    // Final assignment after full addition (assuming sum2 is the corrected sum)
    assign out = sum2;

endmodule

