module bitwise_ops (
    input [7:0] a, b,
    output [7:0] and_out,
    output [7:0] or_out,
    output [7:0] xor_out
);

    // Function to invert bits
    function [7:0] flip;
        input [7:0] a;
        flip = ~a;
    endfunction

    // Perform right shift on a and left shift on b
    wire [7:0] shifted_a = flip(a) >> 1;
    wire [7:0] shifted_b = flip(b) << 1;

    // Bitwise AND of the shifted results
    assign and_out = shifted_a & shifted_b;

    // Function to invert bits (reuse flip function)
    function [7:0] invert;
        input [7:0] a;
        invert = ~a;
    endfunction

    // Invert the AND result to get the final output
    assign or_out = invert(and_out);

    // Hardcode xor_out to 0
    assign xor_out = 8'b0;

endmodule

