    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1)
            mem[i] = 8'h00; // Replace with specific values if needed
    end

    // Output in based on shift address
    assign out = mem[shift];

endmodule

module bitwise_not (
    input [7:0] in,
    output [7:0] out
);

    function [7:0] reverse;
        input [7:0] in;
        integer i, j;
        begin
            reverse = 8'b0;
            for (i = 0; i < 8; i = i + 1) begin
                reverse[i] = in[7 - i];
            end
        end
    endfunction

    assign out = reverse(in);

endmodule

module rotate_left (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);

genvar i;
generate
    for (i = 0; i < 8; i = i + 1) begin : bit_loop
        wire [2:0] shifted_b;
        assign shifted_b = (shift >> i) & 3'd1;
        assign out[i] = in[i] ^ shifted_b;
