module relu (
    input signed [15:0] in_0,
    output signed [15:0] out);
    parameter LEFT = 0;
    parameter RIGHT = 1;

    // Calculate control value
    wire signed [15:0] ctrl = in_0 >> RIGHT;

    // Mask to get left or right part
    wire signed [15:0] masked = ctrl & (((16'b1 << LEFT) - 1) | ((16'b1 << (LEFT + 1)) - 1));

    assign out = masked;
endmodule

