module modular_add_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);

    function [7:0] reverse;
        input [7:0] in;
        integer i;
        begin
            reverse = 8'b0;
            for (i = 7; i >= 0; i = i - 1) begin
                reverse = (reverse | (in[i] ? 8'b1 << (i + 1) : 8'b0)) << 1;
            end
        end
    endfunction

    assign data_out = reverse(data_in);

endmodule

module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010; // Example key, replace with actual key value

    reg [7:0] state;

    // Split input into nibbles
    wire [3:0] upper = data_in[7:4];
    wire [3:0] lower = data_in[3:0];

    // Encrypt upper nibble using KEY
    wire [3:0] encrypted_upper;
    genvar i;
    generate
        for (i = 0; i < 4; i = i + 1) begin : key_schedule_upper
            assign encrypted_upper[i] = (KEY[i] ? ~upper[i] : upper[i]);
        end
    endgenerate

    // Encrypt lower nibble using KEY
    wire [3:0] encrypted_lower;
    generate
        for (i = 0; i < 4; i = i + 1) begin : key_schedule_lower
            assign encrypted_lower[i] = (KEY[i] ? ~lower[i] : lower[i]);
        end
    endgenerate

    // Combine encrypted nibbles (lower gets shifted left by 1)
    assign data_out = {encrypted_upper, encrypted_lower << 1};

    // Debug state update (comments turned off for performance)
    always @(data_in) begin
        state = data_out; // Simplified for example
    end
endmodule

module clock_div2 (
    input clk,
    input rst,
    output clk_out
);
    parameter [7:0] lut_mask = 8'h00;

    // Determine input dependencies
    localparam uses_a = |{(lut_mask[0] ^ lut_mask[1]), (lut_mask[2] ^ lut_mask[3]), 
                        (lut_mask[4] ^ lut_mask[5]), (lut_mask[6] ^ lut_mask[7])};
    localparam uses_b = |{(lut_mask[0] ^ lut_mask[2]), (lut_mask[1] ^ lut_mask[3]), 
                        (lut_mask[4] ^ lut_mask[6]), (lut_mask[5] ^ lut_mask[7])};

    generate
        if (lut_mask == 8'h80) begin : use_case
            reg [7:0] lut_out;

            always @(*) begin
                integer i;
                for (i=0; i<8; i=i+1) begin
                    wire a_slice = (i < 4);
                    wire b_slice = (i[1:0] < 2);
                    wire term = a_slice ? lut_mask[i] : 1'b0;
                    lut_out[i] = term ? clk : 1'b1;
                end
            end
            assign clk_out = &lut_out;
        end else begin : use_table
            reg [7:0] lut_table;

            always @(*) begin
                if (rst) begin
                    lut_table = lut_mask;
                end else begin
                    lut_table = 8'h80;
                end
            end
            assign clk_out = lut_table[7];
        end
    endgenerate
endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);

    // Generate all partial products using AND gates
    wire [3:0][3:0] pp;
    genvar i, j;
    generate
        for (i = 0; i < 4; i = i + 1) begin : gen_i
            for (j = 0; j < 4; j = j + 1) begin : gen_j
                assign pp[i][j] = a[i] & b[j];
            end
        end
    endgenerate

    // Declare intermediate sum and carry signals for carry-save addition
    wire [3:0] sum, carry;

    // Implement carry-save addition for each bit
    // Bit 0
    assign lt = pp[0][0] ^ pp[1][0] ^ pp[2][0] ^ pp[3][0];
    assign carry[0] = pp[0][0] & pp[1][0] | pp[0][0] & pp[2][0] | pp[1][0] & pp[2][0];

    // Bit 1
    assign sum[0] = pp[0][1] ^ pp[1][1] ^ pp[2][1] ^ pp[3][1];
    assign carry[1] = pp[0][1] & pp[1][1] | pp[0][1] & pp[2][1] | pp[1][1] & pp[2][1];

    // Bit 2
    assign sum[1] = pp[0][2] ^ pp[1][2] ^ pp[2][2] ^ pp[3][2];
    assign carry[2] = pp[0][2] & pp[1][2] | pp[0][2] & pp[2][2] | pp[1][2] & pp[2][2];

    // Bit 3
    assign sum[2] = pp[0][3] ^ pp[1][3] ^ pp[2][3] ^ pp[3][3];
    assign carry[3] = pp[0][3] & pp[1][3] | pp[0][3] & pp[2][3] | pp[1][3] & pp[2][3];

    // Compute final gt, eq, lt by combining sum and carry for each bit
    // Bit 0: gt + carry[0] (no carry_in)
    wire c0;
    assign c0 = carry[0];
    assign gt[0] = pp[0][0] ^ c0;
    assign eq[0] = pp[0][0] & c0;

    // Bit 1: gt + carry[1] (carry_in from bit 0)
    wire c1;
    assign c1 = carry[1] ^ c0;
    assign gt[1] = pp[0][1] ^ c1;
    assign eq[1] = pp[0][1] & c1;

    // Bit 2: gt + carry[2] (carry_in from bit 1)
    wire c2;
    assign c2 = carry[2] ^ c1;
    assign gt[2] = pp[0][2] ^ c2;
    assign eq[2] = pp[0][2] & c2;

    // Bit 3: gt + carry[3] (carry_in from bit 2)
    wire c3;
    assign c3 = carry[3] ^ c2;
    assign gt[3] = pp[0][3] ^ c3;
    assign eq[3] = pp[0][3] & c3;

endmodule

module decoder_2to4 (
    input  [1:0] in,
    input        enable,
    output [3:0] out
);

    // 4-bit internal register
    reg [3:0] internal_reg;

    // Update internal register on clock edge or reset
    always @(posedge enable or posedge in[1]) begin
        if (in[1]) begin
            // Async reset: clear all bits
            internal_reg <= 4'b0000;
        end else begin
            // Shift left and insert in[0] as LSB
            internal_reg <= {internal_reg[2:0], in[0]};
        end
    end

    // Output is always the internal register
    assign out = internal_reg;

endmodule

