module demux_1to2 (
    input  in,
    input  sel,
    output out0,
    output out1
);

    // TLB entry registers
    reg [31:0] tlb_entry_addr;
    reg [31:0] tlb_entry_data;
    reg        tlb_entry_valid;

    // DMA request handle
    reg dma_rdy;

    // Interrupt generation
    wire int_flag = tlb_entry_valid && dma_rdy;

    // Integrate QSYS and TLB interactions
    always @(posedge in or posedge sel) begin
        if (sel) begin
            tlb_entry_valid <= 1'b0;
            tlb_entry_addr  <= 32'b0;
            tlb_entry_data  <= 32'b0;
            dma_rdy         <= 1'b0;
        end else if (int_flag) begin
            // Placeholder for interrupt handling
            tlb_entry_valid <= 1'b0;
        end
    end

    // Generate debug outputs
    assign out0 = tlb_entry_valid ? tlb_entry_addr[7:0] : 8'h00;
    assign out1 = tlb_entry_valid ? tlb_entry_data[7:0] : 8'h00;

endmodule

module demux_1to4 (
    input        in,
    input  [1:0] sel,
    output       out0,
    output       out1,
    output       out2,
    output       out3
);

// Configuration parameters
localparam DATA_RATE     = 100_000_000;  // System clock frequency in Hz
localparam BAUD_RATE     = 9600;         // Desirable baud rate
localparam OVERSAMPLING  = 16;           // Oversampling factor
localparam BITS_PER_BYTE = 8;            // Bits per data symbol

// Derived parameters
localparam DESIRED_SAMPLE_TIME = (DATA_RATE / (BAUD_RATE * OVERSAMPLING)) ;
localparam SAMPLE_INTERVAL     = DESIRED_SAMPLE_TIME * BITS_PER_BYTE;
localparam SAMPLE_COUNTER_MAX  = SAMPLE_INTERVAL - 1;
localparam OVERSAMPLE_COUNTER_MAX = (OVERSAMPLING * BITS_PER_BYTE) - 1;

reg [31:0] sample_counter      = 0;
reg [15:0] oversample_counter  = 0;
reg        sample_enable       = 0;
reg        baud_clock_high     = 0;
reg        baud_clock_prev     = 0;
wire       baud_clock_rising   = (baud_clock_high && !baud_clock_prev);

// Generate sample_enable at the start of each data bit
always @(posedge in) begin
    baud_clock_prev <= baud_clock_high;
    if (baud_clock_rising) begin
        sample_enable <= 1'b1;
        sample_counter <= 0;
        // Reset oversample counter after rearming
        if (oversample_counter == OVERSAMPLE_COUNTER_MAX)
            oversample_counter <= 0;
        else
            oversample_counter <= oversample_counter + 1;
    end else begin
        sample_enable <= 1'b0;
    end
end

// Sample accumulator and detect baud clock edges
reg [31:0] accumulator = 0;
reg [31:0] next_accumulator;

always @(posedge in) begin
    next_accumulator = accumulator + sample_enable ? 32'd1 : 32'd0;
    if (sample_counter == SAMPLE_COUNTER_MAX) begin
        accumulator <= next_accumulator;
        sample_enable <= 1'b0;
    end
end

// Detect baud clock rising edge
wire sample_detected = (sample_counter == SAMPLE_COUNTER_MAX) && sample_enable;

// Rearm oversample counter on sample detection
always @(posedge in) begin
    if (sample_detected) begin
        oversample_counter <= OVERSAMPLE_COUNTER_MAX;
    end
end

// Generate baud clock
always @(posedge in) begin
    if (oversample_counter == OVERSAMPLE_COUNTER_MAX)
        oversample_counter <= 0;
end

assign out0 = sample_detected;
assign out2 = sample_detected;
assign out1 = accumulator[31];
assign out3 = baud_clock_high;

endmodule

