assign sout = (load && !rst) ? shift_reg[7] : 1'bz;

always @(posedge clk) begin
    if (load && rst) begin
        shift_reg <= pin;
    end else if (rst && !load) begin
        shift_reg <= {shift_reg[6:0], 1'b0};
    end
end

endmodule

module priority_encoder_4to2 (
    input  [3:0] in,
