module ring_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

    reg [3:0] data_reg;

    // Shift left whenever clk is high
    always @(posedge clk) begin
        if (clk) begin
            data_reg <= {data_reg[2:0], 1'b0};
        end
    end

    // Handle rst on negative clock edge
    always @(negedge rst) begin
        if (rst) begin
            data_reg <= 4'b0;
        end
    end

    assign q = data_reg;

endmodule

module sipo_8bit(
    input clk,
    input rst,
    input sin,
    output [7:0] pout
);

    // 256-byte memory array
    reg [7:0] mem [0:255];

    // Calculate address with wrap-around for 256 bytes
    wire [7:0] address = clk ? (sin ? 8'd0 : (rst ? (clk - 1) : 8'd255)) : 8'd0;

    // Output the pout at the calculated address
    assign pout = mem[address];

endmodule

module siso_8bit(
    input clk,
    input rst,
    input sin,
    output sout
);
    parameter BUFR_DIVIDE = "BYPASS";

    generate
        if (BUFR_DIVIDE == "BYPASS") begin
            // Bypass mode: sout follows sin
            assign sout = sin;
        end else begin
            // Division mode: template for implementation
            // Note: BUFR_DIVIDE should be an integer value (e.g., "2" for divide by 2)
            // Counter and division logic to be implemented here
            reg [31:0] counter;
            always @(posedge clk or posedge rst) begin
                if (rst) begin
                    counter <= 0;
                end else if (sin) begin
                    if (counter == (BUFR_DIVIDE_USE - 1)) begin
                        counter <= 0;
                    end else begin
                        counter <= counter + 1;
                    end
                end
            end
            assign sout = (counter == (BUFR_DIVIDE_USE - 1)) ? 1'b1 : 1'b0;
        end
    endgenerate

    // Convert string parameter to integer (example for implementation)
    // This requires custom handling outside standard Verilog
    wire [31:0] BUFR_DIVIDE_USE = (BUFR_DIVIDE == "2") ? 32'd1 : 
                                  (BUFR_DIVIDE == "4") ? 32'd2 : 
                                  (BUFR_DIVIDE == "8") ? 32'd3 : 
                                  (BUFR_DIVIDE == "16") ? 32'd4 : 
                                  32'd1; // Default to divide by 1

endmodule

module up_counter8(
