module TopModule (
  input p1a,
  input p1b,
  input p1c,
  input p1d,
  output p1y,
  input p2a,
  input p2b,
  input p2c,
  input p2d,
  output p2y
);

  reg [3:0] current_state, next_state;

  parameter EXP = 4'd0;
  parameter RST = 4'd1;
  parameter LOAD = 4'd2;
  parameter COMPARE = 4'd3;
  parameter SUB = 4'd4;
  parameter ADD = 4'd5;
  parameter DONE = 4'd6;

  // State register
  always @(posedge p1a) begin
    if (p1b)
      current_state <= EXP;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      EXP: next_state = RST;
      RST: next_state = p1c ? LOAD : RST;
      LOAD: next_state = COMPARE;
      COMPARE: next_state = p2c ? SUB : ADD;
      SUB: next_state = DONE;
      ADD: next_state = DONE;
      DONE: next_state = p1d ? LOAD : DONE;
      default: next_state = EXP;
    endcase
  end

  // Output logic
  assign p1y = (current_state == LOAD);
  assign p2y = (current_state == DONE);

endmodule

