module TopModule (
  input clk,
  input reset,
  output reg [3:0] q
);

  // State definitions
  localparam IDLE = 2'b00;
  localparam AIMING = 2'b01;
  localparam REACTION = 2'b10;

  reg [1:0] current_state, next_state;
  reg [1:0] timer;

  // State transition and timer logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      current_state <= IDLE;
      timer <= 2'b00;
      q <= 4'b0000;
    end else begin
      current_state <= next_state;
      // Timer increments in AIMING state (2 cycles per clock)
      if (current_state == AIMING)
        timer <= timer + 1'b1;
      else
        timer <= 2'b00;
      // Output logic based on current state
      case (current_state)
        IDLE:    q <= 4'b0000;
        AIMING:  q <= 4'b0100;
        REACTION: q <= 4'b1000;
        default: q <= 4'b0000;
      endcase
    end
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      IDLE:    next_state = (timer == 2'd1) ? AIMING : IDLE;
      AIMING:  next_state = (timer == 2'd2) ? REACTION : AIMING;
      REACTION: next_state = IDLE;
      default: next_state = IDLE;
    endcase
  end

endmodule

