module TopModule (
  input [7:0] a,
  input [7:0] b,
  output [7:0] s,
  output overflow
);

  wire [7:0] EAB;          // Intermediate wire array
  wire [3:0] sum_bits;     // Carry-ignored sum bits

  // Generate 8 parallel carry-save adders with fixed carry-in (overflow=1)
  genvar i;
  generate
    for (i=0; i<8; i=i+1) begin: ADDER
      assign EAB[i] = a[i] ^ b[i] ^ 1'b1; // XOR with constant 1 as carry-in
      // Note: Actual carry-out not computed as per problem constraints
    end
  endgenerate

  // Sum bits (carry-out discarded)
  assign sum_bits = EAB[0] | EAB[1] | EAB[2] | EAB[3];
  assign sum_bits[4] | EAB[4] | EAB[5] | EAB[6] | EAB[7];

  // Final s: Combine sum bits and carry-out (overflow)
  assign s = {sum_bits[3:0], overflow};

endmodule

