    if (x) begin
      state <= IDLE;
      bit_counter <= 3'd0;
      shift_reg <= 8'd0;
      Y0 <= 1'b1;
      z <= 1'b1;
    end else begin
      case (state)
        IDLE: begin
          Y0 <= 1'b1;
          z <= 1'b1;
          if (y == 3'd0) begin
            state <= STARTBIT;
            bit_counter <= 3'd0;
            shift_reg <= 8'd0;
          end
        end
        STARTBIT: begin
          Y0 <= 1'b0;
          z <= 1'b1;
          if (bit_counter == 3'd2) begin
            if (y == 3'd1) begin
              state <= DATABIT;
              bit_counter <= 3'd0;
              shift_reg <= 8'd0;
            end else begin
              state <= IDLE;
            end
          end
        end
        DATABIT: begin
          Y0 <= 1'b1;
          z <= shift_reg[0];
          if (bit_counter == 3'd7) begin
            shift_reg <= shift_reg >> 1;
            bit_counter <= 3'd0;
