              state <= STOPBIT;
            end
          end
        end
        STOPBIT: begin
          Y0 <= 1'b0;
          z <= 1'b0;
          if (bit_counter == 3'd1) begin
            state <= IDLE;
            bit_counter <= 3'd0;
          end
        end
        default: begin
          state <= IDLE;
          bit_counter <= 3'd0;
          shift_reg <= 8'd0;
          Y0 <= 1'b1;
