  always @(*) begin
    case (state)
      s0: begin
        next_state = in ? s2 : s1;
      end
      s1: begin
        next_state = in ? s2 : s1;
      end
      s2: begin
        next_state = in ? s2 : s1;
      end
      default: next_state = s0;
    endcase
  end

  always @(posedge in) begin
