module TopModule (
  input in,
  input [3:0] state,
  output reg [3:0] next_state,
  output out
);

  wire [3:0] D;
  wire [3:0] S;
  wire [3:0] R;

  // Compute D inputs for each flip-flop
  assign D[0] = state[0];  // No feedback for bit 0

  assign D[1] = state[1] ^ next_state[0];  // XOR with current Q0 for bit 1

  wire feedback_2;
  assign feedback_2 = next_state[0] ^ next_state[1];
  assign D[2] = state[2] ^ feedback_2;  // XOR with feedback from Q1 and Q0

  wire feedback_3;
  assign feedback_3 = next_state[0] ^ next_state[1] ^ next_state[2];
  assign D[3] = state[3] ^ feedback_3;  // XOR with feedback from lower bits

  // Compute out output (valid when all bits are stable)
  assign out = &next_state;

  // Update flip-flops on rising clock edge
  always @(posedge in) begin
    next_state[0] <= state[0];
    next_state[1] <= D[1];
    next_state[2] <= D[2];
    next_state[3] <= D[3];
  end

endmodule

