  assign out2 = ~initialized && (state < 1024);

  always @(posedge in) begin
    if (state < 1024) begin
      mem[state] <= next_state;
    end
    if (state == 10'd1023) begin
      initialized <= 1'b1;
    end
  end

endmodule

module TopModule (
