  output done
);
  reg [2:0] cycle_counter;
  reg [7:0] shift_reg;
  reg [7:0] stage1, stage2, stage3;
  reg [2:0] bit_counter;

  assign done = (bit_counter == 3'd7) ? 1'b1 : 1'b0;

  always @(posedge clk) begin
    if (reset) begin
      cycle_counter <= 3'b0;
      shift_reg <= 8'b0;
      stage1 <= 8'b0;
      stage2 <= 8'b0;
      stage3 <= 8'b0;
      bit_counter <= 3'b0;
    end else begin
      if (cycle_counter == 3'd0) begin
        shift_reg <= in;
        bit_counter <= 3'd1;
        cycle_counter <= 3'd1;
      end else if (cycle_counter == 3'd6) begin
        bit_counter <= 3'd0;
        cycle_counter <= 3'd0;
      end else begin
        case (cycle_counter)
          3'd1: begin
            stage1 <= {shift_reg[7], stage1[7:1]};
            bit_counter <= 3'd2;
          end
          3'd2: begin
            stage2 <= {stage1[7], stage2[7:1]};
            bit_counter <= 3'd3;
          end
          3'd3: begin
            stage3 <= {stage2[7], stage3[7:1]};
            bit_counter <= 3'd4;
          end
          3'd4: begin
            stage1 <= {stage3[7], stage1[7:1]};
            bit_counter <= 3'd5;
          end
          3'd5: begin
            stage2 <= {stage1[7], stage2[7:1]};
            bit_counter <= 3'd6;
          end
          default: begin
            // No change for other cycles
          end
        endcase
      end
    end
  end
