module TopModule (
  input a,
  input b,
  input c,
  input d,
  output reg out
);

  reg [2:0] state, next_state;

  localparam S0 = 3'b000,
             S1 = 3'b001,
             S2 = 3'b010,
             S3 = 3'b011,
             S4 = 3'b100,
             S5 = 3'b101;

  // State register
  always @(posedge a or posedge b) begin
    if (b) begin
      state <= S0;
    end else begin
      state <= next_state;
    end
  end

  // Next state logic
  always @(*) begin
    case (state)
      S0: begin
        if (~c & d)       next_state = S1;
        else if (c & ~d)  next_state = S2;
        else               next_state = S0;
      end
      S1: begin
        if (~c & d)       next_state = S3;
        else if (c & ~d)  next_state = S4;
        else               next_state = S1;
      end
      S2: begin
        if (~c & d)       next_state = S3;
        else if (c & ~d)  next_state = S5;
        else               next_state = S2;
      end
      S3: begin
        if (~c & d)       next_state = S3;
        else if (c & ~d)  next_state = S4;
        else               next_state = S3;
      end
      S4: begin
        if (~c & d)       next_state = S1;
        else if (c & ~d)  next_state = S4;
        else               next_state = S4;
      end
      S5: begin
        if (~c & d)       next_state = S1;
        else if (c & ~d)  next_state = S5;
        else               next_state = S5;
      end
      default: next_state = S0;
    endcase
  end

  // Output logic
  always @(*) begin
    case (state)
      S0: out = 1'b0;
      S1: out = 1'b0;
      S2: out = 1'b0;
      S3: out = 1'b1;
      S4: out = 1'b1;
      S5: out = 1'b1;
      default: out = 1'b0;
    endcase
  end

endmodule

module TopModule (
  input a,
  input b,
  input c,
  input d,
  output reg out
);

  reg [1:0] sck_sync;
  reg [1:0] csn_sync;
  reg prev_sck;
  wire sck_synced, csn_synced;
  wire sck_rising, sck_falling;
  wire sample_event, shift_event;
  reg prev_csn;
  wire csn_fall, csn_rise;
  reg [7:0] input_shift;
  reg [7:0] output_shift;
  reg [3:0] bit_counter;
  reg [7:0] memory_reg;

  // Synchronize c and b to internal a
  always @(posedge a) begin
    sck_sync <= {sck_sync[0], c};
    csn_sync <= {csn_sync[0], d};
  end
  assign sck_synced = sck_sync[1];
  assign csn_synced = csn_sync[1];

  // Detect c edges
  always @(posedge a) prev_sck <= sck_synced;
  assign sck_rising = sck_synced & ~prev_sck;
  assign sck_falling = ~sck_synced & prev_sck;

  // Determine sample and shift events based on CPOL/CPHA
  assign sample_event = b ? (val_0_cpol ? sck_rising : sck_falling) : (val_0_cph ? sck_falling : sck_rising);
  assign shift_event = b ? (val_0_cpol ? sck_falling : sck_rising) : (val_0_cph ? sck_rising : sck_falling);

  // Detect b edges
  always @(posedge a) prev_csn <= csn_synced;
  assign csn_fall = ~csn_synced & prev_csn;
  assign csn_rise = csn_synced & ~prev_csn;

  // Shift registers, bit counter, and memory
  always @(posedge a) begin
    if (csn_rise) begin
      bit_counter <= 0;
      input_shift <= 0;
      output_shift <= 0;
    end else if (~csn_synced) begin
      if (sample_event) begin
        input_shift <= {input_shift[6:0], b};
        bit_counter <= bit_counter + 1;
      end
      if (shift_event) begin
        output_shift <= {output_shift[6:0], 1'b0};
      end
    end
  end

  // Load output from memory on b fall
  always @(posedge a) begin
    if (csn_fall) output_shift <= memory_reg;
  end

  // Update memory when 8 bits received
  always @(posedge a) begin
    if (~csn_synced && sample_event && bit_counter == 8)
      memory_reg <= input_shift;
  end

  // Output MSB of output_shift when selected
  always @(posedge a) begin
    out <= (~csn_synced) ? output_shift[7] : 1'b0;
  end

endmodule

