module TopModule (
  input d,
  input done_counting,
  input ack,
  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

  // State definitions (one-hot encoding)
  localparam START     = 10'b0000000001;
  localparam FETCH     = 10'b0000000010;
  localparam DECODE    = 10'b0000000100;
  localparam EXECUTE   = 10'b0000001000;
  localparam WRITEBACK = 10'b0000010000;
  localparam DONE      = 10'b0000100000;

  reg [9:0] current_state, next_state;

  // State register
  always @(posedge d) begin
    if (done_counting)
      current_state <= START;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      START: 
        next_state = ack ? FETCH : START;
      FETCH: 
        next_state = DECODE;
      DECODE: 
        next_state = EXECUTE;
      EXECUTE: 
        next_state = WRITEBACK;
      WRITEBACK: 
        next_state = DONE;
      DONE: 
        next_state = DONE;
      default: 
        next_state = START;
    endcase
  end

  // Output logic
  assign B3_next = (current_state == START);
  assign S_next = (current_state == FETCH);
  assign S1_next     = (current_state == DECODE);
  assign Count_next     = (current_state == EXECUTE);
  assign Wait_next       = (current_state == WRITEBACK);
  assign done       = (current_state == DONE);
  assign counting  = (current_state == FETCH) || (current_state == WRITEBACK);
  assign shift_ena   = (current_state == FETCH) || (current_state == DECODE) || (current_state == EXECUTE) || (current_state == WRITEBACK);

endmodule

module adder_32bit(A,B,S,C32);
     input [32:1] A;
     input [32:1] B;
     output [32:1] S;
     output C32;

     wire [32:1] E_clean;
     wire [32:1] P_clean;
     wire [32:1] G_clean;
     wire [32:1] cleaned_k;
     wire [32:1] cleaned_b;
     wire [32:1] b0_clean;
     wire [32:1] E0_clean;
     wire [32:1] p0_clean;
     wire [32:1] g0_clean;

     // Generate cleaned_k, E_clean, P_clean, G_clean using AND/OR/NOT gates
     generate
         genvar i;
         for (i=1; i<=32; i=i+1) begin: clean_signals
             and and_k(g_clean[i], A[i], B[i]);
             or  or_e(E_clean[i], A[i], B[i]);
             and and_p(P_clean[i], A[i], E_clean[i]);
             not not_g(G_clean[i], P_clean[i]);
         end
     endgenerate

     // Compute b0_clean using AND/OR/NOT gates
     wire [16:0] b0_intermediate;
     wire [16:0] b0_clean_and;
     wire [32:1] b0_clean_or;

     generate
         for (i=0; i<16; i=i+1) begin: b0_intermediate
             and and_b0(b0_intermediate[i], A[i], B[i]);
         end
         for (i=0; i<16; i=i+1) begin: b0_clean_and
             and and_b0_clean(b0_clean_and[i], A[i+16], B[i+16]);
         end
         for (i=0; i<16; i=i+1) begin: b0_clean_or
             or  or_b0(b0_clean_or[i], b0_intermediate[i], b0_clean_and[i]);
         end
     endgenerate
     or  or_b0_clean(b0_clean, b0_clean_or[0], b0_clean_or[1], ..., b0_clean_or[15]);

     // Compute E0_clean using AND/OR/NOT gates
     wire [16:0] E0_clean_intermediate;
     wire [16:0] E0_clean_and;
     wire [32:1] E0_clean_or;

     generate
         for (i=0; i<16; i=i+1) begin: E0_intermediate
             and and_E0(E0_clean_intermediate[i], E_clean[i], E_clean[i+1]);
         end
         for (i=0; i<16; i=i+1) begin: E0_clean_and
             and and_E0_clean(E0_clean_and[i], E_clean[i+1], P_clean[i+1]);
         end
         for (i=0; i<16; i=i+1) begin: E0_clean_or
             or  or_E0(E0_clean_or[i], E0_clean_intermediate[i], E0_clean_and[i]);
         end
     endgenerate
     or  or_E0_clean(E0_clean, E0_clean_or[0], E0_clean_or[1], ..., E0_clean_or[15]);

     // Compute p0_clean using AND/OR/NOT gates
     wire [16:0] p0_clean_intermediate;
     wire [16:0] p0_clean_and;
     wire [32:1] p0_clean_or;

     generate
         for (i=0; i<16; i=i+1) begin: p0_intermediate
             and and_p0(p0_clean_intermediate[i], P_clean[i], E_clean[i+1]);
         end
         for (i=0; i<16; i=i+1) begin: p0_clean_and
             and and_p0_clean(p0_clean_and[i], P_clean[i+1], G_clean[i+1]);
         end
         for (i=0; i<16; i=i+1) begin: p0_clean_or
             or  or_p0(p0_clean_or[i], p0_clean_intermediate[i], p0_clean_and[i]);
         end
     endgenerate
     or  or_p0_clean(p0_clean, p0_clean_or[0], p0_clean_or[1], ..., p0_clean_or[15]);

     // Compute g0_clean using AND/OR/NOT gates
     wire [16:0] g0_clean_intermediate;
     wire [16:0] g0_clean_and;
     wire [32:1] g0_clean_or;

     generate
         for (i=0; i<16; i=i+1) begin: g0_intermediate
             and and_g0(g0_clean_intermediate[i], G_clean[i], E_clean[i+1]);
         end
         for (i=0; i<16; i=i+1) begin: g0_clean_and
             and and_g0_clean(g0_clean_and[i], G_clean[i+1], P_clean[i+1]);
         end
         for (i=0; i<16; i=i+1) begin: g0_clean_or
             or  or_g0(g0_clean_or[i], g0_clean_intermediate[i], g0_clean_and[i]);
         end
     endgenerate
     or  or_g0_clean(g0_clean, g0_clean_or[0], g0_clean_or[1], ..., g0_clean_or[15]);

     // Compute S and C32 using AND/OR/NOT gates
     wire [32:0] val_2_wire;
     wire [32:0] b_wire;

     generate
         for (i=1; i<=32; i=i+1) begin: val_2_and_or
             and if (i == 1) else_and(val_2_wire[i], b0_clean[i], E0_clean[i]);
             or  if (i == 1) else_or(val_2_wire[i], val_2_wire[i-1], p0_clean[i]);
             and if (i == 2) else_and2(val_2_wire[i], val_2_wire[i-1], g0_clean[i]);
         end
     endgenerate
     assign S = val_2_wire[32:1];

     wire [32:0] b_wire_and;
     generate
         for (i=0; i<32; i=i+1) begin: b_and
             and and_b(b_wire_and[i], A[i], B[i]);
         end
     endgenerate
     assign C32 = b_wire_and[0];

endmodule

