module counter_12 
(
  input rst_n,
  input clk,
  input valid_count,

  output reg [3:0] out
);

  // State definitions
  localparam [3:0] A = 4'b0000,
                   B = 4'b0001,
                   C = 4'b0010,
                   D = 4'b0011,
                   E = 4'b0100,
                   F = 4'b0101,
                   G = 4'b0110,
                   H = 4'b0111,
                   I = 4'b1000;

  reg [3:0] current_state, next_state;

  // State register with synchronous reset
  always @(posedge rst_n) begin
    if (clk)
      current_state <= state_A;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      state_A: begin
        if (valid_count)
          next_state = state_F;
        else
          next_state = state_B;
      end
      state_B: next_state = state_B;
      state_C: next_state = state_D;
      state_D: next_state = state_E;
      state_E: next_state = state_E;
      state_F: next_state = state_G;
      state_G: next_state = state_H;
      state_H: next_state = state_I;
      state_I: next_state = state_I;
      default: next_state = state_A;
    endcase
  end

  // Output current state
  always @(*) begin
    out = current_state;
  end

  // Wire assignments for state outputs
  assign out[0] = (current_state == state_B) || (current_state == state_D) || 
                  (current_state == state_E) || (current_state == state_I);
  assign out[1] = (current_state == state_C) || (current_state == state_E);
  assign out[2] = (current_state == state_B) || (current_state == state_D) || 
                   (current_state == state_E) || (current_state == state_F) || 
                   (current_state == state_H) || (current_state == state_I);
  assign out[3] = (current_state == state_F) || (current_state == state_G) || 
                   (current_state == state_H) || (current_state == state_I);

endmodule

module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

reg prev_in;

always @(rst_n, a, clk) begin
	// Check for rising edge of clk (0->1 transition)
	if (clk && !prev_in) begin
		rise <= rst_n;
		down <= a;
	end
	// Update previous input value
	prev_in <= clk;
end

endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;

    reg [3:0] counter;
    wire enable;

    // Clock enable logic
    assign enable = (rst_n & (counter == (NUM_DIV - 1))) | (~rst_n & (counter == 0));

    // Counter behavior
    always @(posedge clk) begin
        if (enable) begin
            counter <= (counter == (NUM_DIV - 1)) ? 4'd0 : counter + 4'd1;
        end else begin
            counter <= 4'd0;
        end
    end

    // Output assignment with reset handling
    always @(posedge clk) begin
        if (enable)
            clk_div <= (counter == (NUM_DIV - 1));
        else
            clk_div <= 1'b0;
    end

endmodule

