module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;

  parameter init = 0,
             A    = 1,
             B    = 2,
             C    = 3,
             D    = 4,
             E    = 5,
             F    = 6,
             G    = 7,
             H    = 8,
             I    = 9,
             Z    = 10,
             garbage = -1;

  reg [3:0] next_state;

  always @(*) begin
    case ({clk, rst})
      2'b00: next_state = init;
      2'b01: next_state = A;
      2'b10: next_state = B;
      2'b11: next_state = C;
      2'b00_C: next_state = D;
      2'b01_CD: next_state = E;
      2'b10_E: next_state = F;
      2'b01_F: next_state = G;
      2'b10_G: next_state = H;
      2'b01_H: next_state = I;
      2'b10_I: next_state = Z;
      2'b01_Z: next_state = garbage;
      default: next_state = garbage;
    endcase
  end

  always @(posedge clk, negedge rst) begin
    if (~rst)
      out <= init;
    else
      out <= next_state;
  end

endmodule

