module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

parameter START=2'b00,
          STATE1=2'b01,
          STATE2=2'b10,
          STATE3=2'b11;

reg [1:0] current_state, next_state;

always @(posedge IN) begin
    if (CLK)
        current_state <= START;
    else
        current_state <= next_state;
end

always @(*) begin
    case (current_state)
        START: next_state = RST ? STATE1 : STATE2;
        STATE1: next_state = RST ? STATE3 : STATE2;
        STATE2: next_state = RST ? STATE1 : STATE3;
        STATE3: next_state = RST ? STATE3 : STATE2;
        default: next_state = START;
    endcase
end

always @(*) begin
    if (current_state == STATE3 && !RST)
        MATCH = 1'b1;
    else
        MATCH = 1'b0;
end

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

    wire [3:0] D = d;
    reg [3:0] Q;
    wire [3:0] J, K;

    // Compute J and K for each bit
    assign J[0] = (D[0] & ~Q[0]) | (~D[0] & Q[0]);  // J0 = D0 XOR Q0
    assign K[0] = ~J[0];                            // K0 = ~J0

    assign J[1] = (D[1] & ~Q[1]) | (~D[1] & Q[1]);  // J1 = D1 XOR Q1
    assign K[1] = ~J[1];                            // K1 = ~J1

    assign J[2] = (D[2] & ~Q[2]) | (~D[2] & Q[2]);  // J2 = D2 XOR Q2
    assign K[2] = ~J[2];                            // K2 = ~J2

    assign J[3] = (D[3] & ~Q[3]) | (~D[3] & Q[3]);  // J3 = D3 XOR Q3
    assign K[3] = ~J[3];                            // K3 = ~J3

    // Implement JK flip-flop for bit 0
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            Q[0] <= 1'b0;
        else case ({J[0], K[0]})
            2'b00: Q[0] <= Q[0];
            2'b01: Q[0] <= 1'b0;
            2'b10: Q[0] <= 1'b1;
            2'b11: Q[0] <= ~Q[0];
        endcase
    end

    // Implement JK flip-flop for bit 1
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            Q[1] <= 1'b0;
        else case ({J[1], K[1]})
            2'b00: Q[1] <= Q[1];
            2'b01: Q[1] <= 1'b0;
            2'b10: Q[1] <= 1'b1;
            2'b11: Q[1] <= ~Q[1];
        endcase
    end

    // Implement JK flip-flop for bit 2
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            Q[2] <= 1'b0;
        else case ({J[2], K[2]})
            2'b00: Q[2] <= Q[2];
            2'b01: Q[2] <= 1'b0;
            2'b10: Q[2] <= 1'b1;
            2'b11: Q[2] <= ~Q[2];
        endcase
    end

    // Implement JK flip-flop for bit 3
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            Q[3] <= 1'b0;
        else case ({J[3], K[3]})
            2'b00: Q[3] <= Q[3];
            2'b01: Q[3] <= 1'b0;
            2'b10: Q[3] <= 1'b1;
            2'b11: Q[3] <= ~Q[3];
        endcase
    end

    assign valid_out = Q[3];
    assign dout = Q[0];

endmodule

